const params = $('Parse Batch Manifest').first().json;
const items = $input.all();

const registered = items
  .map(item => item.json)
  .filter(item => item && (item.asset_id || item.assetId));

const processed = registered.filter(item =>
  item.moveStatus === 'processed' ||
  item.status === 'raw' ||
  item.asset_id ||
  item.assetId
);

const selected = processed[processed.length - 1];

if (!params.autoPromoteLatest || !selected) {
  return [{
    json: {
      orchestratorStatus: 'registered_only',
      reason: !params.autoPromoteLatest ? 'autoPromoteLatest is false' : 'No registered asset returned',
      registeredCount: registered.length,
      params,
      registered
    }
  }];
}

return [{
  json: {
    ...params,
    assetId: selected.asset_id || selected.assetId,
    selectedAsset: selected,
    registeredCount: registered.length,
    registered
  }
}];

const params = $('Parse Batch Manifest').first().json;
return [{
  json: {
    avatar: params.avatar,
    scene: params.scene,
    assetType: params.assetType,
    baseUrl: params.baseUrl
  }
}];

const fs = require('fs');
const path = require('path');

function isMissing(value) {
  return value === undefined || value === null || value === '' || value === 'undefined';
}

function uniqueTargetPath(targetDir, sourceName) {
  const parsed = path.parse(sourceName);
  let candidate = path.join(targetDir, sourceName);
  let index = 1;
  while (fs.existsSync(candidate)) {
    candidate = path.join(targetDir, `${parsed.name}-${index}${parsed.ext}`);
    index++;
  }
  return candidate;
}

function moveFile(sourcePath, targetPath) {
  try {
    fs.renameSync(sourcePath, targetPath);
  } catch (error) {
    if (error && error.code === 'EXDEV') {
      fs.copyFileSync(sourcePath, targetPath);
      fs.unlinkSync(sourcePath);
    } else {
      throw error;
    }
  }
}

function moveManifest(params, status) {
  const sourceDir = params.manifestSourceFile?.directory || params.inputDir;
  const sourceName = params.manifestSourceFile?.name || params.manifestFileName || 'batch.json';
  const targetDir = status === 'failed' ? params.failedDir : params.processedDir;

  if (isMissing(sourceDir) || isMissing(sourceName) || isMissing(targetDir)) {
    return {
      moveStatus: 'skipped',
      moveReason: 'Missing manifest path metadata',
      sourceDir,
      sourceName,
      targetDir
    };
  }

  fs.mkdirSync(targetDir, { recursive: true });

  const sourcePath = path.join(sourceDir, sourceName);
  const targetPath = uniqueTargetPath(targetDir, sourceName);

  if (!fs.existsSync(sourcePath)) {
    return {
      moveStatus: 'skipped',
      moveReason: 'Manifest file not found',
      attemptedSource: sourcePath
    };
  }

  moveFile(sourcePath, targetPath);

  return {
    moveStatus: 'processed',
    movedFrom: sourcePath,
    movedTo: targetPath
  };
}

const params = $('Parse Batch Manifest').first().json;
const selected = $('Select Asset To Promote').first().json;
const canonical = $input.first().json || null;
const registered = selected.registered || [];
const duplicates = registered.filter(item => item.duplicated === true || item.moveStatus === 'duplicate');
const processed = registered.filter(item => item.moveStatus === 'processed' || item.asset_id || item.assetId);
const manifestMove = moveManifest(params, 'processed');

return [{
  json: {
    status: 'completed',
    registeredCount: registered.length,
    processedCount: processed.length,
    duplicatesCount: duplicates.length,
    promotedAssetId: selected.assetId,
    canonicalUrl: canonical?.url || null,
    canonical: canonical || null,
    manifest: {
      moveStatus: manifestMove.moveStatus,
      movedFrom: manifestMove.movedFrom,
      movedTo: manifestMove.movedTo,
      moveReason: manifestMove.moveReason || null
    },
    registered,
    duplicates
  }
}];

