const params = $('Parse Batch Manifest').first().json;
const data = $input.first().json;
const registered = data.registered || [];
const duplicates = registered.filter(item => item.duplicated === true || item.moveStatus === 'duplicate');
const processed = registered.filter(item => item.moveStatus === 'processed' || item.asset_id || item.assetId);
const manifestMove = moveManifest(params, 'processed');

return [{
  json: {
    status: data.orchestratorStatus || 'registered_only',
    reason: data.reason || null,
    registeredCount: data.registeredCount || registered.length || 0,
    processedCount: processed.length,
    duplicatesCount: duplicates.length,
    promotedAssetId: null,
    canonicalUrl: null,
    canonical: null,
    manifest: {
      moveStatus: manifestMove.moveStatus,
      movedFrom: manifestMove.movedFrom,
      movedTo: manifestMove.movedTo,
      moveReason: manifestMove.moveReason || null
    },
    registered,
    duplicates
  }
}];

const runtime = $('Set Runtime Paths').first().json;
const itemIndex = 0;
const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, 'data');
const raw = buffer.toString('utf8');

let manifest;
try {
  manifest = JSON.parse(raw);
} catch (error) {
  throw new Error(`Invalid batch.json: ${error.message}`);
}

const required = [
  'avatar',
  'avatarShort',
  'scene',
  'assetType',
  'workflow',
  'model'
];

const missing = required.filter(field => manifest[field] === undefined || manifest[field] === null || manifest[field] === '');

if (missing.length > 0) {
  throw new Error(`batch.json missing required fields: ${missing.join(', ')}`);
}

return [{
  json: {
    inputDir: manifest.inputDir || runtime.inputDir,
    processedDir: manifest.processedDir || runtime.processedDir,
    duplicatesDir: manifest.duplicatesDir || runtime.duplicatesDir,
    failedDir: manifest.failedDir || runtime.failedDir,
    baseUrl: manifest.baseUrl || runtime.baseUrl,
    manifestFileName: runtime.manifestFileName || 'batch.json',
    manifestSourceFile: {
      name: $input.first().binary.data.fileName || runtime.manifestFileName || 'batch.json',
      directory: $input.first().binary.data.directory || runtime.inputDir
    },

    avatar: manifest.avatar,
    avatarShort: manifest.avatarShort,
    scene: manifest.scene,
    assetType: manifest.assetType,
    workflow: manifest.workflow,
    model: manifest.model,
    seed: manifest.seed ?? null,
    version: manifest.version ?? 1,
    parentAssetId: manifest.parentAssetId || '',
    autoPromoteLatest: manifest.autoPromoteLatest !== false,

    manifest
  }
}];

const fs = require('fs');
const path = require('path');

const row = $input.first().json;
const errors = [];

if (!row.avatar_exists) {
  errors.push(`Unknown or inactive avatar: ${row.avatar}`);
}

if (!row.scene_exists) {
  errors.push(`Unknown or inactive scene for avatar: ${row.avatar}/${row.scene}`);
}

if (!row.asset_type_exists) {
  errors.push(`Unknown or inactive assetType: ${row.asset_type}`);
}

if (!row.generation_exists) {
  errors.push(`Unknown or inactive workflow/model: ${row.workflow}/${row.model}`);
}

if (row.catalog_avatar_short && row.avatar_short !== row.catalog_avatar_short) {
  errors.push(`avatarShort mismatch. batch.json=${row.avatar_short}, catalog=${row.catalog_avatar_short}`);
}

const inputDir = row.input_dir;
const allowedExtensions = new Set(['.png', '.jpg', '.jpeg', '.webp']);
let imageFiles = [];

if (!fs.existsSync(inputDir)) {
  errors.push(`Input directory does not exist: ${inputDir}`);
} else {
  imageFiles = fs.readdirSync(inputDir)
    .filter(name => allowedExtensions.has(path.extname(name).toLowerCase()))
    .sort();
}

if (imageFiles.length === 0) {
  errors.push(`No image files found in inputDir: ${inputDir}`);
}

if (errors.length > 0) {
  throw new Error(`Invalid batch manifest: ${errors.join(' | ')}`);
}

return [{
  json: {
    inputDir: row.input_dir,
    processedDir: row.processed_dir,
    duplicatesDir: row.duplicates_dir,
    failedDir: row.failed_dir,
    baseUrl: row.base_url,
    manifestFileName: row.manifest_file_name,
    manifestSourceFile: {
      name: row.manifest_source_file_name,
      directory: row.manifest_source_file_directory
    },

    avatar: row.avatar,
    avatarShort: row.catalog_avatar_short || row.avatar_short,
    scene: row.scene,
    assetType: row.asset_type,
    workflow: row.workflow,
    model: row.model,
    seed: row.seed,
    version: row.version || 1,
    parentAssetId: row.parent_asset_id || '',
    autoPromoteLatest: row.auto_promote_latest !== false,

    catalogValidation: {
      avatarExists: row.avatar_exists,
      sceneExists: row.scene_exists,
      assetTypeExists: row.asset_type_exists,
      generationExists: row.generation_exists,
      imageCount: imageFiles.length,
      imageFiles
    }
  }
}];
